1	import { BottomSheetModalProvider } from "@gorhom/bottom-sheet";
2	import { animateParallel, Block, Text } from "@prototyp/skeletor";
3	import { FlashList, type FlashListRef } from "@shopify/flash-list";
4	import {
5	  type EventTimelineItem,
6	  ProfileDetails_Tags,
7	  type RoomInterface,
8	} from "@unomed/react-native-matrix-sdk";
9	import { format } from "date-fns";
10	import { useAtom, useSetAtom } from "jotai";
11	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
12	import { getEventId } from "modules/matrix-client/utils";
13	import { TimelineAtoms } from "modules/timeline/jotai";
14	import {
15	  type FC,
16	  useCallback,
17	  useEffect,
18	  useMemo,
19	  useRef,
20	  useState,
21	} from "react";
22	import { Dimensions, Image, Modal, StyleSheet, View } from "react-native";
23	import { useMediaTimeline } from "screens/room-media/hooks";
24	import { ImageInfoBottomSheet } from "screens/room/fragments/image-info-bottom-sheet";
25	import { VideoInfoBottomSheet } from "screens/room/fragments/video-info-bottom-sheet";
26	import { Colors, TextSize } from "shared/styles";
27	import { BlurGradientOverlay } from "../blur-gradient-overlay";
28	import { Button } from "../button";
29	import { MediaEdgePage } from "./MediaEdgePage";
30	import { MediaImagePage } from "./MediaImagePage";
31	import { MediaVideoPage } from "./MediaVideoPage";
32	import { getMediaKind } from "./utils";
33	
34	const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get("window");
35	
36	const OLDER_EDGE_KEY = "__older_edge__";
37	
38	type ViewerPage =
39	  | { kind: "event"; event: EventTimelineItem }
40	  | { kind: "older-edge" };
41	
42	interface Props {
43	  payload: MediaViewerPayload;
44	}
45	
46	export const MediaViewerModalContent: FC<Props> = ({ payload }) => {
47	  const [, setPayload] = useAtom(TimelineAtoms.mediaViewerPayload);
48	  const setImageInfoPayload = useSetAtom(TimelineAtoms.imageInfoPayload);
49	  const setVideoInfoPayload = useSetAtom(TimelineAtoms.videoInfoPayload);
50	  const listRef = useRef<FlashListRef<ViewerPage>>(null);
51	  const [showControls, setShowControls] = useState(true);
52	  const [currentIndex, setCurrentIndex] = useState(0);
53	  const localUriByEventIdRef = useRef<Map<string, string | null>>(new Map());
54	
55	  const room = useMemo<RoomInterface | undefined>(() => {
56	    try {
57	      return MatrixCore.getRoom(payload.roomId);
58	    } catch {
59	      return undefined;
60	    }
61	  }, [payload.roomId]);
62	
63	  const { mediaItems, loading, loadMore, reachedStart } = useMediaTimeline({
64	    room,
65	    roomId: payload.roomId,
66	  });
67	
68	  /** Filtered events sorted newest-first. */
69	  const events = useMemo<EventTimelineItem[]>(() => {
70	    const filtered = mediaItems.filter((item) => getMediaKind(item) !== null);
71	    return filtered.length === 0 ? [payload.initialEvent] : filtered;
72	  }, [mediaItems, payload.initialEvent]);
73	
74	  /** FlashList data: events + the older-edge sentinel when more history
75	  remains. Sentinel is a trailing "loading" page: swiping into it triggers
76	  `loadMore`, and when new events arrive they're inserted between the last
77	  real event and the sentinel, so the user slides from the spinner straight
78	  onto the newest item of the just-loaded batch. We suppress the sentinel
79	  while the hook's initial pagination is still in flight so the seeded
80	  single-item render can't accidentally land on it. */
81	  const pages = useMemo<ViewerPage[]>(() => {
82	    const result: ViewerPage[] = events.map((event) => ({
83	      kind: "event",
84	      event,
85	    }));
86	    if (!loading && !reachedStart) {
87	      result.push({ kind: "older-edge" });
88	    }
89	    return result;
90	  }, [events, loading, reachedStart]);
91	
92	  /** Pages-index for the tapped event — resolved against the hydrated list. */
93	  const initialPageIndex = useMemo(() => {
94	    const eventIdx = events.findIndex(
95	      (event) => getEventId(event) === payload.initialEventId,
96	    );
97	    return eventIdx >= 0 ? eventIdx : 0;
98	  }, [events, payload.initialEventId]);
99	
100	  // Sync `currentIndex` with `initialPageIndex` until the list mounts against
101	  // the hydrated data — otherwise the header reads from pages[0] (wrong
102	  // event) while the seeded-single-item pass is still on screen.
103	  const syncedIndexRef = useRef(false);
104	  useEffect(() => {
105	    if (loading) return;
106	    if (syncedIndexRef.current) return;
107	    syncedIndexRef.current = true;
108	    setCurrentIndex(initialPageIndex);
109	  }, [loading, initialPageIndex]);
110	
111	  const currentPage = pages[currentIndex];
112	  const currentEvent =
113	    currentPage?.kind === "event"
114	      ? currentPage.event
115	      : loading
116	        ? payload.initialEvent
117	        : null;
118	  const currentKind = currentEvent ? getMediaKind(currentEvent) : null;
119	
120	  // If `reachedStart` flips while the user is on the older-edge sentinel, the
121	  // sentinel disappears from `pages` and the current index points past the
122	  // end. Snap back to the last real event so the viewer isn't blank.
123	  useEffect(() => {
124	    if (!reachedStart) return;
125	    if (currentIndex < events.length) return;
126	    const targetIndex = Math.max(0, events.length - 1);
127	    listRef.current?.scrollToIndex({ index: targetIndex, animated: false });
128	    setCurrentIndex(targetIndex);
129	  }, [reachedStart, events.length, currentIndex]);
130	
131	  const senderName = useMemo(() => {
132	    if (!currentEvent) return null;
133	    if (currentEvent.senderProfile.tag === ProfileDetails_Tags.Ready) {
134	      return (
135	        currentEvent.senderProfile.inner.displayName ?? currentEvent.sender
136	      );
137	    }
138	    return currentEvent.sender;
139	  }, [currentEvent]);
140	
141	  const formattedDate = useMemo(() => {
142	    if (!currentEvent) return null;
143	    return format(Number(currentEvent.timestamp), "MMM d, HH:mm");
144	  }, [currentEvent]);
145	
146	  const controlsAnimation = useRef(
147	    animateParallel(
148	      { translateY: [-120, 0], opacity: [0, 1] },
149	      { duration: 280 },
150	    ),
151	  ).current;
152	
153	  useEffect(() => {
154	    if (showControls) controlsAnimation.start();
155	    else controlsAnimation.reverse();
156	  }, [showControls]);
157	
158	  const onClose = useCallback(() => {
159	    setPayload(null);
160	  }, [setPayload]);
161	
162	  const handleSingleTap = useCallback(() => {
163	    setShowControls((prev) => !prev);
164	  }, []);
165	
166	  const handleViewableItemsChanged = useCallback(
167	    ({ viewableItems }: { viewableItems: { index: number | null }[] }) => {
168	      const first = viewableItems[0];
169	      if (first?.index == null) return;
170	      setCurrentIndex(first.index);
171	    },
172	    [],
173	  );
174	
175	  // Paginate once the user lands on the older-edge sentinel. The hook's
176	  // internal guards (isPaginatingRef / reachedStartRef) stop duplicate calls.
177	  useEffect(() => {
178	    if (currentPage?.kind === "older-edge") loadMore();
179	  }, [currentPage, loadMore]);
180	
181	  const handleLocalUriChange = useCallback(
182	    (eventId: string | null, uri: string | null) => {
183	      if (!eventId) return;
184	      localUriByEventIdRef.current.set(eventId, uri);
185	    },
186	    [],
187	  );
188	
189	  const handleOpenInfo = useCallback(() => {
190	    if (!currentEvent) return;
191	    const eventId = getEventId(currentEvent);
192	    const localUri = eventId
193	      ? (localUriByEventIdRef.current.get(eventId) ?? null)
194	      : null;
195	    if (currentKind === "image") {
196	      setImageInfoPayload({
197	        event: currentEvent,
198	        roomId: payload.roomId,
199	        localUri,
200	      });
201	    } else if (currentKind === "video") {
202	      setVideoInfoPayload({
203	        event: currentEvent,
204	        roomId: payload.roomId,
205	        localUri,
206	      });
207	    }
208	  }, [
209	    currentEvent,
210	    currentKind,
211	    payload.roomId,
212	    setImageInfoPayload,
213	    setVideoInfoPayload,
214	  ]);
215	
216	  const keyExtractor = useCallback((page: ViewerPage) => {
217	    if (page.kind === "older-edge") return OLDER_EDGE_KEY;
218	    return getEventId(page.event) ?? "";
219	  }, []);
220	
221	  const renderItem = useCallback(
222	    ({ item, index }: { item: ViewerPage; index: number }) => {
223	      if (item.kind === "older-edge") {
224	        return <MediaEdgePage />;
225	      }
226	      const event = item.event;
227	      const kind = getMediaKind(event);
228	      const eventId = getEventId(event);
229	      const onUriChange = (uri: string | null) =>
230	        handleLocalUriChange(eventId, uri);
231	      return (
232	        <View style={styles.page}>
233	          {kind === "image" ? (
234	            <MediaImagePage
235	              event={event}
236	              onSingleTap={handleSingleTap}
237	              onLocalUriChange={onUriChange}
238	            />
239	          ) : kind === "video" ? (
240	            <MediaVideoPage
241	              event={event}
242	              isActive={index === currentIndex}
243	              onSingleTap={handleSingleTap}
244	              onLocalUriChange={onUriChange}
245	            />
246	          ) : null}
247	        </View>
248	      );
249	    },
250	    [currentIndex, handleSingleTap, handleLocalUriChange],
251	  );
252	
253	  return (
254	    <Modal
255	      visible
256	      animationType="fade"
257	      statusBarTranslucent
258	      transparent
259	      onRequestClose={onClose}
260	    >
261	      <BottomSheetModalProvider>
262	        <Block background={Colors.black} flex={1}>
263	          <FlashList
264	            // Remount when the hook's initial pagination completes so that
265	            // `initialScrollIndex` is re-evaluated against the hydrated list
266	            // and lands on the tapped event's real index. FlashList applies
267	            // `initialScrollIndex` only once at mount, so without this remount
268	            // the list stays anchored to the seeded single-item position.
269	            key={loading ? "loading" : "hydrated"}
270	            ref={listRef}
271	            data={pages}
272	            renderItem={renderItem}
273	            keyExtractor={keyExtractor}
274	            horizontal
275	            inverted
276	            pagingEnabled
277	            showsHorizontalScrollIndicator={false}
278	            initialScrollIndex={initialPageIndex}
279	            onViewableItemsChanged={handleViewableItemsChanged}
280	          />
281	
282	          <Block
283	            absolute
284	            offsets={{ top: 0, left: 0, right: 0 }}
285	            zIndex={10}
286	            paddings={[56, 20, 16, 20]}
287	            flexDirection="row"
288	            align="center"
289	            justify="space-between"
290	            gap={12}
291	            background={Colors.primary}
292	            animations={controlsAnimation.animations}
293	            pointerEvents={showControls ? "auto" : "none"}
294	          >
295	            <BlurGradientOverlay />
296	            <Block width={60} align="flex-start" zIndex={2}>
297	              {!!currentEvent && (
298	                <Button.Wrapper onPress={handleOpenInfo}>
299	                  <Image
300	                    source={require("assets/icons/info.png")}
301	                    style={styles.infoIcon}
302	                    tintColor={Colors.white}
303	                  />
304	                </Button.Wrapper>
305	              )}
306	            </Block>
307	            <Block flex={1} align="center" gap={2} zIndex={2}>
308	              {senderName && (
309	                <Text
310	                  color={Colors.white}
311	                  font="InstrumentSans-Semibold"
312	                  numberOfLines={1}
313	                >
314	                  {senderName}
315	                </Text>
316	              )}
317	              {formattedDate && (
318	                <Text
319	                  size={TextSize.tiny}
320	                  color={Colors.white80}
321	                  numberOfLines={1}
322	                >
323	                  {formattedDate}
324	                </Text>
325	              )}
326	            </Block>
327	            <Block width={60} align="flex-end" zIndex={2}>
328	              <Button.Wrapper onPress={onClose}>
329	                <Text font="InstrumentSans-Semibold" color={Colors.white}>
330	                  Close
331	                </Text>
332	              </Button.Wrapper>
333	            </Block>
334	          </Block>
335	        </Block>
336	        <ImageInfoBottomSheet />
337	        <VideoInfoBottomSheet />
338	      </BottomSheetModalProvider>
339	    </Modal>
340	  );
341	};
342	
343	const styles = StyleSheet.create({
344	  page: {
345	    width: SCREEN_WIDTH,
346	    height: SCREEN_HEIGHT,
347	  },
348	  infoIcon: {
349	    width: 24,
350	    height: 24,
351	  },
352	});
353

